<?php
 namespace QQWorld\Test\Integrity\Library\PhpParser; use QQWorld\TestFramework\Integrity\Library\PhpParser\Throws; class ThrowsTest extends \PHPUnit\Framework\TestCase { protected $throws; protected $tokens; public function setUp() { $this->tokens = $this->getMockBuilder( \QQWorld\TestFramework\Integrity\Library\PhpParser\Tokens::class )->disableOriginalConstructor()->getMock(); } public function testGetDependencies() { $tokens = [ 0 => [T_THROW, 'throw'], 1 => [T_WHITESPACE, ' '], 2 => [T_NEW, 'new'], 3 => [T_WHITESPACE, ' '], 4 => [T_NS_SEPARATOR, '\\'], 5 => [T_STRING, 'Exception'], 6 => '(', ]; $this->tokens->expects($this->any())->method('getTokenCodeByKey')->will( $this->returnCallback( function ($k) use ($tokens) { return $tokens[$k][0]; } ) ); $this->tokens->expects($this->any())->method('getTokenValueByKey')->will( $this->returnCallback( function ($k) use ($tokens) { return $tokens[$k][1]; } ) ); $throws = new Throws($this->tokens); foreach ($tokens as $k => $token) { $throws->parse($token, $k); } $uses = $this->getMockBuilder( \QQWorld\TestFramework\Integrity\Library\PhpParser\Uses::class )->disableOriginalConstructor()->getMock(); $uses->expects($this->once())->method('hasUses')->will($this->returnValue(true)); $uses->expects($this->once())->method('getClassNameWithNamespace')->will($this->returnValue('\Exception')); $this->assertEquals(['\Exception'], $throws->getDependencies($uses)); } } 